import {blueprints,layouts,projectBlueprint,inferBlueprint} from './blueprints.js';
import {initialState,restoreState,createProject,createFromPrompt,transition,inspectImport,sampleImport,frameworks,fileMap,readiness} from './state.js';

let previewSearch='';
const KEY='architect2.workspace.v1';
let state;try{state=restoreState(localStorage.getItem(KEY));}catch{state=initialState();}
let route=location.hash.slice(1)||'home',tab='preview',selectedFile='app.config.json',search='',filter='All',buildStep=0,timer=null,modalReturn=null;
const drafts=new Map();
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const icons={home:'⌂',build:'▦',agents:'◈',data:'▤',test:'✓',github:'⑂',deploy:'↗',history:'↶',settings:'⚙',template:'▧'};
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const p=()=>state.projects.find(p=>p.id===state.active);
const button=(text,action,cls='',extra='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;
const badge=(text,tone='')=>`<span class="badge ${tone}">${e(text)}</span>`;
const icon=(name)=>`<span class="icon" aria-hidden="true">${icons[name]||'◇'}</span>`;
const empty=(title,body,action='')=>`<div class="empty"><span class="empty-symbol" aria-hidden="true">◇</span><h3>${title}</h3><p>${body}</p>${action}</div>`;
function notify(text,error=false){const n=document.querySelector('#notifications');n.textContent=text;n.className=error?'notice error':'notice';clearTimeout(notify.timer);notify.timer=setTimeout(()=>{n.className='';n.textContent='';},6000);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{notify('Browser storage is unavailable or full. Export your project to keep a copy.',true);}}
function dispatchFor(id,type,data){state.projects=state.projects.map(x=>x.id===id?transition(x,{type,data}):x);save();render();}
function dispatch(type,data){const project=p();if(!project)throw new Error('Open a project first.');state.projects=state.projects.map(x=>x.id===project.id?transition(x,{type,data}):x);save();render();}
function go(next){route=next;location.hash=next;render();document.querySelector('#main')?.focus({preventScroll:true});}
window.addEventListener('hashchange',()=>{route=location.hash.slice(1)||'home';render();});
function startProject(project){previewSearch='';state.projects.unshift(project);state.active=project.id;save();closeModal();go(project.importInfo?'build':'plan');}
function header(title,sub,action=''){return `<div class="page-heading"><div><div class="eyebrow">${sub}</div><h1>${title}</h1></div>${action}</div>`;}
function shell(content){const project=p();return `<div class="shell"><aside class="sidebar"><a class="brand" href="#home"><span class="brand-mark">A</span>architect<span class="version">2.0</span></a><div class="workspace-picker"><span class="avatar">H</span><div>Personal workspace<small>Assignment prototype</small></div></div><nav aria-label="Workspace"><a href="#home" class="${route==='home'?'active':''}">${icon('home')}Overview</a><a href="#templates" class="${route==='templates'?'active':''}">${icon('template')}Discover & templates</a>${project?`<div class="nav-label">CURRENT PROJECT</div><div class="project-name">${e(project.name)}</div>${[['plan','Outcome & plan','◷'],['build','Build workspace','▦'],['structure','App structure','▧'],['agents','Agents','◈'],['data','Data & connections','▤'],['test','Test scenarios','✓'],['github','GitHub','⑂'],['deploy','Release','↗'],['history','History','↶'],['settings','Settings & people','⚙']].map(([id,label,sym])=>`<a href="#${id}" class="${route===id?'active':''}"><span class="icon" aria-hidden="true">${sym}</span>${label}${id==='deploy'&&readiness(project).some(c=>!c.ok)?'<span class="nav-count">!</span>':''}</a>`).join('')}`:''}</nav><div class="sidebar-bottom"><button class="demo-note" data-action="about"><span class="demo-dot"></span>Demo environment <span>ⓘ</span></button><div class="account"><span class="avatar small">${state.session?'R':'G'}</span><div>${state.session?'Reviewer':'Guest'}<small>Saved on this device</small></div>${button(state.session?'Sign out':'Sign in','auth','quiet')}</div></div></aside><div class="main-shell"><header class="topbar"><div class="breadcrumb">Workspace <span>/</span> ${project&& !['home','templates'].includes(route)?e(project.name):'Overview'}</div><div class="top-actions">${project?`<div class="mode-switch" role="group" aria-label="Workspace view"><button data-action="mode" data-value="guided" aria-pressed="${state.mode==='guided'}">Guided</button><button data-action="mode" data-value="technical" aria-pressed="${state.mode==='technical'}">Technical</button></div>${button('Share','share','quiet')}${button('Release '+icon('deploy'),'release','primary')}`:button('Open reviewer demo','demo','primary')}</div></header><main id="main" tabindex="-1">${content}</main><footer class="app-footer"><span>Local prototype · Sample data · Simulated external services</span><button data-action="about">What works?</button></footer></div></div>`;}
function home(){return `<div class="home-content">${header('What do you want to build?','ARCHITECT 2.0 / APP BUILDER',button('Import existing project','import','outline'))}<section class="outcome-card"><div class="outcome-copy"><span class="eyebrow light">YOUR IDEA. YOUR AGENTS. YOUR APPLICATION.</span><h2>Build agentic apps.<br>From a prompt or your code.</h2><p>Bring an idea, choose a starting point, or continue an existing project. Plan, build, inspect, and release in one workspace.</p></div><form id="new-project" class="prompt-box"><label for="outcome">Describe the application you want to build</label><textarea id="outcome" name="outcome" required rows="3" placeholder="An AI research workspace that turns questions into sourced briefs…"></textarea><div class="prompt-bottom"><div class="blueprint-select"><label for="app-type">Starting point</label><select id="app-type" name="blueprint"><option value="auto">Suggest from my prompt</option>${Object.values(blueprints).map(b=>`<option value="${b.id}">${e(b.name)}</option>`).join('')}</select></div><button class="btn lime" type="submit">Create application ↗</button></div></form><div class="quick-start">Explore a workflow ${['support','sales','research'].map(id=>button(e(blueprints[id].name),'template','chip',`data-value="${id}"`)).join('')}</div></section><div class="platform-paths"><button data-action="template" data-value="custom"><strong>＋ Start from scratch</strong><span>Define your own app, data, and agents</span></button><button data-action="import"><strong>⑂ Bring your existing project</strong><span>Inspect files, frameworks, and configuration</span></button><button data-action="discover"><strong>⌁ Explore an opportunity</strong><span>Find a useful starting point for your team</span></button></div><div class="section-heading"><h2>Your applications <span class="muted">${state.projects.length.toString().padStart(2,'0')}</span></h2><label class="search">⌕ <input aria-label="Search projects" placeholder="Find an application" id="project-search" value="${e(search)}"></label></div><div class="project-grid">${state.projects.filter(x=>x.name.toLowerCase().includes(search.toLowerCase())).map(x=>`<button class="project-card" data-action="open-project" data-id="${x.id}"><div class="mini-preview theme-${projectBlueprint(x).color}"><div class="mini-sidebar"></div><div class="mini-lines"><span></span><span></span><span></span></div><span class="mini-label">${e(projectBlueprint(x).category)} / ${e(x.layout)}</span></div><div class="project-card-body"><div class="row"><h3>${e(x.name)}</h3><span>↗</span></div><p>${e(x.outcome)}</p><div class="row"><span>${x.agents.length} agents · ${e(x.framework)}</span>${badge(x.builtRevision?'Preview ready':'Planning',x.builtRevision?'green':'')}</div></div></button>`).join('')||empty(search?'No matching applications':'Your workspace is ready.',search?'Try another name.':'Start with a prompt, use a template, or bring your existing work.',button('Explore reviewer demo','demo','primary'))}</div><div class="section-heading"><h2>Different ideas. One platform.</h2><a href="#templates">Browse all templates ↗</a></div><div class="template-grid">${['support','sales','research'].map(id=>templateCard(id)).join('')}</div></div>`;}
function templateCard(id){const b=blueprints[id];return `<button class="template-card theme-${b.color}" data-action="template" data-value="${id}"><span class="template-icon">${b.symbol}</span><span class="eyebrow">${e(b.category)}</span><h3>${e(b.name)}</h3><p>${e(b.outcome)}</p><span class="template-link">${b.agents.length} agents · ${e(b.layout)} layout ↗</span></button>`;}
function templates(){return `<div class="page-content">${header('A starting point for every idea.','TEMPLATE LIBRARY',button('Find a use case','discover','primary'))}<p class="page-intro">Each template includes its own agent roles, workflow, knowledge requirements, and interactive app preview. Customize any part of it.</p><div class="filter-row" role="group" aria-label="Template category">${['All','Customer support','Sales','Research','People','EPC & manufacturing','Custom'].map(x=>button(e(x),'filter',filter===x?'selected':'quiet',`data-value="${e(x)}"`)).join('')}</div><div class="template-grid">${Object.values(blueprints).filter(b=>filter==='All'||b.category===filter).map(b=>templateCard(b.id)).join('')}</div><section class="panel spaced"><div class="row"><div><h2>Reusable agents, across applications</h2><p>Inspect a sample Studio review coordinator and attach it to the current project.</p></div>${button('Browse Studio agent','studio','outline')}</div></section></div>`;}
function plan(){const x=p(),b=projectBlueprint(x);return `<div class="page-content">${header('Shape the application before you build.','01 / PLAN',badge(x.approved?'Approved · editable':'Needs your review',x.approved?'green':'amber'))}<div class="two-column"><form id="plan-form" class="panel"><div class="panel-heading"><span class="step-circle">01</span><div><h2>Application brief</h2><p>${e(b.category)} starting point · editable by you</p></div></div><label for="plan-name">Application name</label><input id="plan-name" name="name" value="${e(x.name)}" required maxlength="80"><label for="plan-outcome">What should the application do?</label><textarea name="outcome" id="plan-outcome" required rows="4">${e(x.outcome)}</textarea><label for="audience">Who will use it?</label><input id="audience" name="audience" value="${e(x.audience)}" required><div class="form-grid"><div><label for="owner">Who reviews uncertain outputs?</label><input id="owner" name="owner" value="${e(x.owner)}" required></div><div><label for="threshold">Human review below (%)</label><input id="threshold" name="threshold" type="number" min="50" max="99" required value="${x.threshold}"></div></div><div class="callout"><strong>You control the starting point.</strong><p>Plans use configurable blueprints in this demo. Choose a different layout, edit agent roles, and add your own data. Free-form AI generation is simulated.</p></div><div class="form-error" role="alert"></div><button class="btn primary" type="submit">Approve plan & inspect agents ↗</button></form><div><section class="panel blueprint"><div class="eyebrow">PROPOSED APPLICATION</div><h2>${e(x.headline)}</h2>${x.agents.map((a,i)=>`<div class="flow-step"><span>${i+1}</span><div><h3>${e(a.name)}</h3><p>${e(a.role)}</p></div></div>`).join('')}<div class="divider"></div><div class="row"><span>${x.agents.length} agents</span><span>${e(x.layout)} preview</span><span>${x.fields.length} custom fields</span></div><a href="#structure">Customize app structure ↗</a></section><section class="assumptions"><h3>Confirm before connecting real data</h3><ul><li>Input: ${e(x.agents[0]?.input||'Your project input')}.</li><li>Knowledge: ${e(x.knowledge[0]||'Define the source')}.</li><li>Review owner: ${e(x.owner)}.</li></ul><p>These are editable project assumptions.</p></section></div></div></div>`;}
function chat(){const x=p();return `<aside class="chat-pane"><div class="chat-title"><span class="agent-spark">✳</span><div><h2>Build together</h2><p>One conversation. Every layer.</p></div></div><div class="chat-messages">${x.messages.slice(-6).map(m=>`<div class="message ${m.role}"><div class="message-role">${m.role==='user'?'YOU':'ARCHITECT'}</div><p>${e(m.text)}</p></div>`).join('')}<div class="plan-summary"><div class="row"><strong>Current plan</strong>${badge('r'+x.revision)}</div><p>${e(x.outcome)}</p><div class="summary-line">${icon('agents')} ${x.agents.length} agents · ${e(x.framework)}</div><div class="summary-line">${icon('data')} ${x.knowledge.length} source · ${x.threshold}% review threshold</div><a href="#plan">Edit the brief ↗</a></div>${x.pending?impact(x):''}</div><form id="chat-form" class="chat-compose"><label for="change-request">What would you like to change?</label><textarea name="text" id="change-request" rows="3" required placeholder="Add team alerts, or switch to a board layout"></textarea><div class="form-error" role="alert"></div><div class="row"><span class="subtle">5 supported edit types</span><button class="btn primary" type="submit">Review impact ↗</button></div></form><div class="suggestions">${button('Add Teams alerts','suggest','chip',`data-value="Add Teams alerts"`)}${button('Review below 90%','suggest','chip',`data-value="Set confidence threshold to 90"`)}${button('12-hour response','suggest','chip',`data-value="Set response to 12 hours"`)}</div></aside>`;}
function impact(x){return `<section class="impact-card"><div class="row"><span class="eyebrow">CHANGE IMPACT</span>${badge('Not applied','amber')}</div><h3>${e(x.pending.title)}</h3><p>Review the connected changes before they become part of your app.</p>${x.pending.impact.map((i,n)=>`<div class="impact-layer"><span class="layer-number">0${n+1}</span><div><strong>${i.layer}</strong><p>${e(i.detail)}</p></div></div>`).join('')}${state.mode==='technical'?`<pre class="diff">${e(Object.entries(x.pending.patch).map(([k,v])=>`- ${k}: ${JSON.stringify(x[k])}\n+ ${k}: ${JSON.stringify(v)}`).join('\n'))}</pre>`:''}<div class="button-row">${button('Apply change','apply','primary')}${button('Discard','discard','quiet')}</div></section>`;}
function build(){const x=p();return `<div class="build-layout">${chat()}<section class="work-pane"><div class="work-toolbar"><div class="tabs" role="group" aria-label="Workspace panel">${[['preview','Preview'],['flow','Agent flow'],['design','App structure'],...(state.mode==='technical'?[['code','Files & config'],['logs','Logs']]:[])].map(([id,name])=>`<button data-action="work-tab" data-value="${id}" aria-pressed="${tab===id}">${name}</button>`).join('')}</div><div class="toolbar-actions">${x.undo?button('↶ Undo','undo','quiet'):''}${badge('Revision '+x.revision)}${button('Export','export','quiet')}</div></div>${x.stage==='building'?`<div class="build-progress"><span class="spinner"></span><h2>${['Preparing agent contracts','Wiring sample knowledge','Building the review interface','Checking the preview'][buildStep]||'Checking the preview'}</h2><p>Your plan stays available if you cancel.</p><progress max="4" value="${buildStep+1}" aria-label="Build progress"></progress>${button('Cancel build','cancel-build','outline')}</div>`:!x.builtRevision?empty(x.stage==='cancelled'?'Build paused. Your work is safe.':'Your plan is ready to take shape.',x.approved?'Build the sample app to interact with real local state. Generation is deterministic in this prototype.':'Approve the outcome plan before building.',button(x.stage==='cancelled'?'Retry build':'Build preview','build-start','primary',x.approved?'':'disabled')):tab==='preview'?preview(x):tab==='flow'?agentFlow(x):tab==='design'?structurePanel(x):tab==='code'?codePanel(x):logs(x)}<div class="work-bottom"><span>${x.stage==='built'?'✓ Local preview ready':e(x.stage)} · ${e(x.framework)}</span><a href="#test">Test a scenario →</a></div></section></div>`;}
function preview(x){const b=projectBlueprint(x),records=x.records.filter(r=>(r.title+' '+r.area).toLowerCase().includes(previewSearch.toLowerCase()));const card=r=>`<button class="exception" data-action="exception" data-id="${e(r.id)}"><span class="severity-mark ${r.severity.toLowerCase()}"></span><span class="exception-main"><span class="record-id">${e(r.id)} · ${e(r.area)}</span><strong>${e(r.title)}</strong><span>${e(r.status)} · ${r.confidence*100<x.threshold?'Human review required':'Draft ready'}</span></span>${badge(r.severity,r.severity==='High'?'red':'amber')}<span>↗</span></button>`;return `<div class="preview-wrap"><div class="browser-bar"><div class="browser-dots"><i></i><i></i><i></i></div><span>Preview / ${e(x.name)}</span>${badge('Local app · sample data')}</div><div class="sample-app theme-${b.color}"><header class="sample-header"><div class="sample-brand"><span>${b.symbol}</span>${e(x.name)}</div><span class="sample-account">${e(x.audience)}</span></header><div class="sample-content"><div class="row"><div><div class="eyebrow">${e(b.category)}</div><h2>${e(x.headline)}</h2></div>${button('+ Add '+e(x.entity),'add-record','outline')}</div><div class="sample-stats"><div><span>Total ${e(x.plural)}</span><strong>${x.records.length.toString().padStart(2,'0')}</strong></div><div><span>Human review below</span><strong>${x.threshold}<small>%</small></strong></div><div><span>Response window</span><strong>${x.sla}<small>h</small></strong></div></div><div class="row sample-list-heading"><h3>${e(x.plural[0].toUpperCase()+x.plural.slice(1))}</h3>${badge(x.notifications?'Team alerts on':'Draft actions only',x.notifications?'green':'')}</div><label class="preview-search" for="preview-search">Search ${e(x.plural)}<input id="preview-search" type="search" placeholder="Search by title or context" value="${e(previewSearch)}"></label>${!records.length?empty(x.records.length?'No matching items':'Your application is ready for its first '+e(x.entity),x.records.length?'Try another search.':'Add a record to try the workflow. It stays in this browser.',button('Add '+e(x.entity),'add-record','primary')):x.layout==='board'?`<div class="kanban">${x.stages.map(stage=>`<section class="kanban-column"><div class="row"><h3>${e(stage)}</h3>${badge(records.filter(r=>(r.stage||x.stages[0])===stage).length)}</div>${records.filter(r=>(r.stage||x.stages[0])===stage).map(card).join('')||'<p class="subtle">No items in this stage.</p>'}</section>`).join('')}</div>`:x.layout==='briefs'?`<div class="brief-grid">${records.map(r=>`<button class="brief-card" data-action="exception" data-id="${e(r.id)}"><span class="eyebrow">${e(r.stage||x.stages[0])}</span><h3>${e(r.title)}</h3><p>${e(r.description)}</p><span>${e(r.area)}</span><div class="divider"></div><strong>Open brief ↗</strong></button>`).join('')}</div>`:records.map(card).join('')}<div class="sample-footnote">Sample content · Human-reviewed outputs · External agent execution is simulated.</div></div></div></div>`;}
function agentFlow(x){return `<div class="flow-canvas"><div class="eyebrow">AGENT WORKFLOW / ${e(x.framework)}</div><h2>${x.agents.length} roles, connected around your outcome.</h2><div class="graph-flow">${x.agents.map((a,i)=>`<div class="graph-node"><div class="row"><span class="agent-icon">◈</span><span class="eyebrow">0${i+1}</span></div><h3>${e(a.name)}</h3><p>${e(a.role)}</p><small>${e(a.input)} → ${e(a.output)}</small></div>`).join('<div class="graph-connector" aria-hidden="true">↓</div>')}</div><div class="human-gate">✓ Human review · ${e(x.owner)} · confidence below ${x.threshold}% escalates</div><div class="button-row">${button('Configure agents','agents','outline')}${button('Run a scenario','test','primary')}</div></div>`;}
function structure(){return '<div class="page-content">'+header('Make the app your own.','APPLICATION STRUCTURE')+structurePanel(p())+'</div>';}
function structurePanel(x){return `<form id="structure-form" class="panel structure-panel"><div class="row"><div><h2>App layout & data</h2><p>These settings change the actual local preview and exported configuration.</p></div>${badge(projectBlueprint(x).category)}</div><label for="layout">Preview layout</label><select name="layout" id="layout">${layouts.map(l=>`<option ${l===x.layout?'selected':''}>${l}</option>`).join('')}</select><label for="headline">App heading</label><input id="headline" name="headline" required value="${e(x.headline)}"><div class="form-grid"><div><label for="entity">Record label · singular</label><input id="entity" name="entity" required value="${e(x.entity)}"></div><div><label for="plural">Record label · plural</label><input id="plural" name="plural" required value="${e(x.plural)}"></div></div><label for="fields">Custom fields · comma separated</label><input id="fields" name="fields" required value="${e(x.fields.join(', '))}"><label for="stages">Workflow stages · comma separated</label><input id="stages" name="stages" required value="${e(x.stages.join(', '))}"><div class="form-error" role="alert"></div><button class="btn primary" type="submit">Save application structure</button><p class="subtle">1–8 custom fields and 2–5 stages. Existing records keep a valid stage when the workflow changes.</p></form>`;}
function codePanel(x){const files=fileMap(x);if(!files[selectedFile])selectedFile=Object.keys(files)[0];return `<div class="code-workspace"><div class="file-tree"><span class="eyebrow">PROJECT FILES</span>${Object.keys(files).map(f=>button(e(f),'file',selectedFile===f?'file active':'file',`data-value="${f}"`)).join('')}</div><div class="code-editor"><div class="row"><strong>${selectedFile}</strong>${badge('Derived from project')}</div><pre><code>${e(files[selectedFile])}</code></pre>${selectedFile==='app.config.json'?`<form id="config-form"><label for="config-json">Edit app configuration</label><textarea id="config-json" name="config" rows="8" spellcheck="false">${e(files[selectedFile])}</textarea><div class="form-error" role="alert"></div><button class="btn primary" type="submit">Review configuration diff</button></form>`:'<p class="subtle">Edit instructions and framework in Agents. Tool contracts follow the notification setting.</p>'}</div></div>`;}
function logs(x){return `<div class="logs"><h2>Project events</h2><p>Local transition log. No external runtime is connected.</p>${x.history.map(h=>`<div class="log-line"><span>r${h.revision}</span><strong>${e(h.title)}</strong><p>${e(h.detail)}</p></div>`).join('')}</div>`;}
function agents(){const x=p();return `<div class="page-content">${header('Build the agent team your app needs.','AGENTS & ORCHESTRATION',button('+ Add agent','add-agent','primary'))}<div class="agent-overview">${x.agents.map((a,i)=>`<section class="role-card"><span class="agent-icon">◈</span><h3>${e(a.name)}</h3><p>${e(a.role)}</p>${badge(a.id==='studio-review'?'Studio reference':'Step '+(i+1))}<div class="button-row">${button('Edit agent','edit-agent','outline',`data-id="${e(a.id)}"`)}${button('Remove','remove-agent','quiet',`data-id="${e(a.id)}" ${x.agents.length===1?'disabled':''}`)}</div></section>`).join('')}</div><div class="two-column"><form id="agent-form" class="panel"><h2>Runtime & primary agent</h2><label for="instructions">Primary agent instructions</label><textarea id="instructions" name="instructions" rows="6" required>${e(x.instructions)}</textarea><div class="form-grid"><div><label for="framework">Framework contract</label><select id="framework" name="framework">${frameworks.map(f=>`<option ${x.framework===f?'selected':''}>${f}</option>`).join('')}</select></div><div><label for="model">Model profile</label><select id="model" name="model">${['Balanced · sample model','Fast · sample model','Reasoning · sample model'].map(f=>`<option ${x.model===f?'selected':''}>${f}</option>`).join('')}</select></div></div><p class="subtle">Contract configuration is editable. Live framework adapters and model execution are simulated.</p><div class="form-error" role="alert"></div><button type="submit" class="btn primary">Save agent configuration</button></form><div><section class="panel"><h2>Shared tools & knowledge</h2>${x.tools.map(t=>`<div class="tool-row"><span>⌁</span><div><strong>${e(t)}</strong><small>${t==='knowledge.search'?'Read project knowledge':t==='review.create'?'Create a draft review assignment':'Notify the project channel after approval'}</small></div>${badge(t==='teams.notify'&&x.connections.teams!=='connected'?'Needs permission':'Configured')}</div>`).join('')}<div class="divider"></div>${x.knowledge.map(k=>`<p>▤ ${e(k)}</p>`).join('')}<a href="#data">Manage sources and connections ↗</a></section><section class="panel spaced"><h3>Reuse an existing Studio agent</h3><p>Attach a sample review coordinator to this workflow, preserving its reference and role.</p>${button(x.studio?'Studio agent attached':'Browse Studio library','studio','outline')}<div class="button-row">${button('Test agents','test','outline')}${button(x.builtRevision?'Open workspace':'Build preview','build-start','primary',(!x.approved&&!x.importInfo)?'disabled':'')}</div></section></div></div></div>`;}
function data(){const x=p();return `<div class="page-content">${header('Give your agents the right context.','DATA & CONNECTIONS',button('Add knowledge source','add-source','outline'))}<div class="callout compact"><strong>Sample connections</strong><span>No real account access or credentials are used. Explore missing permissions and recovery safely.</span></div><div class="connection-grid">${[['knowledge','▤','Project knowledge','Read this application’s knowledge sources','read:project-documents'],['teams','T','Microsoft Teams','Notify your project channel','send:project-channel'],['model','✳','Model provider','Run the selected agent profile','MODEL_API_KEY']].map(([key,symbol,title,desc,scope])=>`<section class="panel connection"><div class="row"><span class="connection-logo">${symbol}</span>${badge(x.connections[key],x.connections[key]==='connected'||x.connections[key]==='sample'?'green':x.connections[key]==='denied'?'red':'amber')}</div><h2>${title}</h2><p>${desc}</p><code>${scope}</code>${x.connections[key]==='denied'?'<p class="inline-error">Permission denied. Grant the required sample scope to reconnect.</p>':''}<div class="button-row">${button(x.connections[key]==='connected'?'Manage connection':'Set up connection','connect','outline',`data-key="${key}"`)}</div></section>`).join('')}</div><div class="two-column spaced"><section class="panel"><h2>Knowledge sources</h2>${x.knowledge.map((k,i)=>`<div class="source-row"><span>▤</span><div><strong>${e(k)}</strong><small>${i?'Metadata added locally':projectBlueprint(x).citation}</small></div>${badge('Sample')}</div>`).join('')}<p class="subtle">No uploaded documents are sent to a model or indexed in this prototype.</p></section><section class="panel"><h2>Data explorer</h2><p>Collection: <code>${e(x.collection)}</code> · local sample rows</p><div class="table-scroll"><table><thead><tr><th>ID</th><th>Severity</th><th>Status</th></tr></thead><tbody>${x.records.map(r=>`<tr><td>${r.id}</td><td>${r.severity}</td><td>${e(r.status)}</td></tr>`).join('')}</tbody></table></div><details><summary>View collection schema</summary><pre>{ id: string, title: string, severity: string,
  confidence: number, owner: string, status: string }</pre></details></section></div></div>`;}
function testPage(){const x=p();const latest=x.tests[0];return `<div class="page-content">${header('Test the moments that matter.','SCENARIO LAB',badge('Deterministic simulation'))}<div class="two-column"><section class="panel"><h2>Choose a scenario</h2><p>Inspect the route, cited evidence, and failure reason before releasing.</p><form id="test-form"><label for="scenario">Test case</label><select id="scenario" name="kind"><option value="suite">Release suite · connection and routing checks</option><option value="normal">${e(x.records[1]?.title||x.records[0]?.title||"Project input")} · sample route</option><option value="uncertain">Incomplete evidence · human review</option><option value="timeout">Provider timeout · failure drill</option></select><div class="callout"><strong>Expected behavior</strong><p>Uncertain outputs go to ${e(x.owner)}. Missing connections stop the run with a useful recovery step.</p></div><button class="btn primary" type="submit">Run sample test</button></form><p class="subtle">Passing proves this prototype’s state rules. It is not a measured evaluation of a language model.</p></section><section class="panel">${latest?`<div class="row"><h2>Run result</h2>${badge(latest.passed?'Passed':'Failed',latest.passed?'green':'red')}</div><p>${latest.error?e(latest.error):'Route: '+e(latest.route)+' · '+e(latest.citation)}</p><div class="test-trace">${latest.trace.map((t,i)=>`<div><span class="trace-step">${i+1}</span>${e(t)}</div>`).join('')}</div><div class="row subtle"><span>Revision ${latest.revision}</span><span>${latest.suite?'Release suite':'Single scenario'}</span></div><div class="button-row">${latest.passed?button('Review release checks','release','primary'):button('Fix connections','data','outline')}${button('Retry normal scenario','retry-test','quiet')}</div>`:empty('No runs yet','Run a sample scenario to inspect the result and trace.')}</section></div><section class="panel spaced"><h2>Run history</h2>${x.tests.length?`<div class="table-scroll"><table><thead><tr><th>Scenario</th><th>Revision</th><th>Result</th><th>What happened</th></tr></thead><tbody>${x.tests.map(t=>`<tr><td>${e(t.kind)}</td><td>${t.revision}</td><td>${t.passed?'Passed':'Failed'}</td><td>${e(t.error||t.route)}</td></tr>`).join('')}</tbody></table></div>`:'<p>Configuration changes clear stale results. The event history preserves prior run events.</p>'}</section></div>`;}
function github(){const x=p();return `<div class="page-content">${header('Keep ownership of your work.','GITHUB',badge('Simulated integration'))}<div class="two-column"><section class="panel"><div class="row"><span class="connection-logo">⑂</span>${badge(x.github.connected?'Connected to sample account':'Not connected',x.github.connected?'green':'amber')}</div><h2>Your source, your workflow.</h2><p>Review exactly where changes will go. This screen models GitHub; no real repository is changed here.</p>${!x.github.connected?button('Connect sample GitHub','github-connect','primary'):`<form id="github-form"><label for="repo">Repository</label><select id="repo" name="repo">${[x.github.repo,'sample-org/agent-app','sample-org/research-workspace'].filter((v,i,a)=>a.indexOf(v)===i).map(r=>`<option>${e(r)}</option>`).join('')}</select><label for="branch">Branch</label><input id="branch" name="branch" value="${e(x.github.branch)}" required><label class="checkbox"><input type="checkbox" name="automatic" ${x.github.automatic?'checked':''}> Automatically sync subsequent changes</label><div class="form-error" role="alert"></div><button class="btn outline" type="submit">Save destination</button></form>`}</section><section class="panel"><div class="row"><h2>Change review</h2>${badge(x.github.syncedRevision===x.revision?'In sync':'Pending changes',x.github.syncedRevision===x.revision?'green':'amber')}</div><p>Project revision ${x.revision} → ${e(x.github.branch)}</p><pre class="diff">${e(x.github.syncedRevision===x.revision?'No changes waiting.':`+ app.config.json\n+ agents/workflow.contract.json\n+ tools/contracts.json\n\n+ reviewBelow: ${x.threshold}\n+ responseHours: ${x.sla}\n+ notifications: ${x.notifications}`)}</pre>${x.github.conflict?`<div class="callout danger"><strong>Conflicting response window</strong><p>Local: ${x.sla} hours. Sample remote: 48 hours. Choose deliberately; then test the accepted configuration.</p><div class="button-row">${button('Keep local','resolve-local','outline')}${button('Accept remote · 48h','resolve-remote','outline')}</div></div>`:''}<div class="button-row">${button('Sync sample changes','sync','primary',!x.github.connected||x.github.conflict?'disabled':'')}${button('Simulate conflict','conflict','quiet',!x.github.connected?'disabled':'')}</div></section></div>${x.importInfo?`<section class="panel spaced"><h2>Imported project inspection</h2><div class="stat-row"><div><span>Framework</span><strong>${e(x.importInfo.framework)}</strong></div><div><span>Entry points</span><strong>${x.importInfo.files.length} files</strong></div><div><span>Dependencies</span><strong>${e(x.importInfo.dependencies.join(', '))}</strong></div></div><p>Missing configuration at import: ${e(x.importInfo.requiredEnv.join(', ')||'None')}. The import reads the manifest, not a remote repository.</p></section>`:''}</div>`;}
function deploy(){const x=p(),checks=readiness(x),ready=checks.every(c=>c.ok);return `<div class="page-content">${header('A release you can explain.','RELEASE',badge(`${checks.filter(c=>c.ok).length}/${checks.length} checks ready`,ready?'green':'amber'))}<div class="two-column"><section class="panel"><h2>Before this goes live</h2><p>Checks follow the current project state. Fix a blocker where it belongs, then return here.</p><div class="readiness">${checks.map(c=>`<div class="check-row"><span class="check-icon ${c.ok?'ok':'blocked'}">${c.ok?'✓':'!'}</span><span>${c.label}</span>${c.ok?badge('Ready','green'):`<a href="#${c.target}">Resolve →</a>`}</div>`).join('')}</div><form id="deploy-form"><label for="release-scenario">Release scenario</label><select id="release-scenario" name="scenario"><option value="healthy">Healthy release</option><option value="fail">Health-check timeout · recovery drill</option></select><button type="submit" class="btn primary full" ${!ready||x.releaseStatus==='deploying'?'disabled':''}>${x.releaseStatus==='deploying'?'Releasing sample app…':'Deploy sample release ↗'}</button></form><p class="subtle">This demonstrates deployment decisions. It does not publish the sample app to an external service.</p></section><div><section class="panel release-status ${x.releaseStatus==='success'?'success-panel':''}"><span class="release-symbol">${x.releaseStatus==='success'?'✓':x.releaseStatus==='failed'?'!':'↗'}</span><h2>${x.releaseStatus==='success'?'Your demo release is ready.':x.releaseStatus==='failed'?'Release paused. Your app is safe.':x.releaseStatus==='deploying'?'Preparing the release…':'From preview to a shared release.'}</h2><p>${x.releaseStatus==='failed'?e(x.releaseError):x.releaseStatus==='success'?'The simulated release is active. Share the hosted Architect prototype with its sample environment clearly identified.':'A versioned snapshot preserves the app and agent configuration you reviewed.'}</p>${x.releaseStatus==='deploying'?'<progress aria-label="Deployment in progress"></progress>':''}${x.releaseStatus==='failed'?button('Retry healthy release','retry-deploy','primary'):x.releaseStatus==='success'?`<div class="button-row">${button('Open released preview','released-preview','primary')}${button('Share prototype','share','outline')}</div>`:''}</section><section class="panel spaced"><h2>Release history</h2>${x.releases.length?x.releases.map(r=>`<div class="release-row"><div><strong>Version ${r.version}</strong><small>Revision ${r.revision} · ${new Date(r.time).toLocaleDateString()}</small></div>${r.id===x.activeRelease?badge('Active','green'):button('Rollback','rollback','outline',`data-id="${r.id}"`)}</div>`).join(''):'<p>No releases yet. Complete the checks to create the first version.</p>'}</section></div></div></div>`;}
function history(){return `<div class="page-content">${header('Every decision leaves a trail.','HISTORY',p().undo?button('Undo last applied change','undo','outline'):'')}${logs(p())}</div>`;}
function settings(){const x=p();return `<div class="page-content">${header('A workspace that stays accountable.','SETTINGS & PEOPLE',button('Export project','export','outline'))}<div class="two-column"><form id="settings-form" class="panel"><h2>Project settings</h2><label for="project-name">Project name</label><input name="name" id="project-name" required value="${e(x.name)}"><label for="budget">Illustrative monthly budget (USD)</label><input name="budget" id="budget" type="number" min="1" step="1" required value="${x.budget}"><div class="form-error" role="alert"></div><button type="submit" class="btn primary">Save settings</button><div class="divider"></div><h3>Usage visibility</h3><div class="stat-row"><div><span>Sample runs</span><strong>${x.runs}</strong></div><div><span>Illustrative cost</span><strong>$${(x.runs*0.02).toFixed(2)}</strong></div><div><span>Budget</span><strong>$${x.budget}</strong></div></div><progress aria-label="Illustrative budget usage" max="${x.budget}" value="${x.runs*0.02}"></progress><p class="subtle">Planning assumption: $0.02 per run, not a provider quote. No paid inference occurs.</p></form><section class="panel"><h2>People with access</h2><p>Local collaboration flow. Invites are not sent and permissions are not enforced by a server.</p><div class="member-row"><span class="avatar">R</span><strong>Reviewer</strong>${badge('Owner')}</div>${x.members.map(m=>`<div class="member-row"><span class="avatar">${e(m.email[0].toUpperCase())}</span><strong>${e(m.email)}</strong>${badge(m.role)}</div>`).join('')}<form id="member-form"><label for="member-email">Collaborator email</label><input id="member-email" name="email" type="email" required placeholder="teammate@example.com"><label for="member-role">Role</label><select id="member-role" name="role"><option>Reviewer</option><option>Editor</option></select><div class="form-error" role="alert"></div><button class="btn outline" type="submit">Add to local access list</button></form></section></div><section class="panel spaced"><div class="row"><div><h2>Start a fresh walkthrough</h2><p>Reset clears only this prototype’s data on this device. Export first if you want to keep it.</p></div>${button('Reset demo','reset','danger-button')}</div></section></div>`;}
function render(){if(!['home','templates'].includes(route)&&!p())route='home';if(state.mode==='guided'&&['code','logs'].includes(tab))tab='preview';const pages={home,templates,plan,build,structure,agents,data,test:testPage,github,deploy,history,settings};app.innerHTML=shell((pages[route]||home)());for(const input of app.querySelectorAll('input[id],textarea[id],select[id]')){const saved=drafts.get((state.active||'home')+':'+input.id);if(saved!==undefined){if(input.type==='checkbox')input.checked=saved;else input.value=saved;}}}
function showModal(title,html){modalReturn=document.activeElement;modal.innerHTML=`<div class="modal-heading"><h2 id="modal-title">${title}</h2>${button('×','close','close-button','aria-label="Close dialog"')}</div><div class="modal-body">${html}</div>`;if(!modal.open)modal.showModal();}
function closeModal(){modal.close();modalReturn?.focus?.();}
function auth(){showModal('Welcome to Architect',`<p>Use a local demo identity to explore the full workflow. No real authentication or password collection.</p><form id="auth-form"><label for="demo-name">Display name</label><input id="demo-name" name="name" required placeholder="Your name or Reviewer"><label for="demo-role">What brings you here?</label><select id="demo-role" name="role"><option>Build a business workflow</option><option>Work with an existing codebase</option></select><button class="btn primary full" type="submit">Continue in demo</button></form><div class="divider"></div>${button('Skip sign-in · reviewer demo','demo','outline full')}`);}
function importDialog(){showModal('Bring your existing work',`<p>Import a project manifest to inspect its framework, entrypoints, dependencies, and missing configuration. Source cloning is simulated.</p><div class="button-row">${button('Load sample repository','load-sample','outline')}</div><form id="import-form"><label for="import-json">Project manifest (JSON)</label><textarea id="import-json" name="manifest" rows="11" spellcheck="false" required placeholder='{"name":"My app","framework":"LangGraph",…}'></textarea><div class="form-error" role="alert"></div><button class="btn primary" type="submit">Inspect & import</button></form>`);}

function agentDialog(id){const a=p().agents.find(a=>a.id===id)||{name:'',role:'',instructions:'',input:'',output:'',tools:['knowledge.search']};showModal(id?'Edit agent':'Add an agent',`<form id="agent-detail-form"><input type="hidden" name="id" value="${e(id||'')}">${[['name','Agent name'],['role','Role'],['input','Input contract'],['output','Output contract']].map(([key,label])=>`<label for="agent-${key}">${label}</label><input id="agent-${key}" name="${key}" required value="${e(a[key])}">`).join('')}<label for="agent-detail-instructions">Instructions</label><textarea id="agent-detail-instructions" name="instructions" required rows="4">${e(a.instructions)}</textarea><fieldset><legend>Allowed tools</legend>${['knowledge.search','review.create'].map(t=>`<label class="checkbox"><input type="checkbox" name="tools" value="${t}" ${a.tools.includes(t)?'checked':''}>${t}</label>`).join('')}</fieldset><div class="form-error" role="alert"></div><button class="btn primary" type="submit">Save agent</button></form>`);}
function recordDialog(){const x=p();showModal('Add '+e(x.entity),`<form id="record-form"><label for="record-title">Title</label><input id="record-title" name="title" required><label for="record-description">Description</label><textarea id="record-description" name="description" rows="3"></textarea><label for="record-context">Context</label><input id="record-context" name="area"><label for="record-priority">Priority</label><select id="record-priority" name="severity"><option>Medium</option><option>High</option><option>Low</option></select>${x.fields.map((field,i)=>`<label for="field${i}">${e(field)}</label><input id="field${i}" name="field${i}">`).join('')}<div class="form-error" role="alert"></div><button class="btn primary" type="submit">Add to application</button></form>`);}

function connectDialog(key){const names={knowledge:'Project knowledge',teams:'Microsoft Teams',model:'Model provider'};showModal(names[key],`<p>This is a simulated connection. No credential entry is needed.</p><div class="callout"><strong>Requested scope</strong><p>${key==='knowledge'?'Read only the sources attached to this project.':key==='teams'?'Send draft notifications to the project channel. Human approval remains required.':'Use a local deterministic response fixture. No model API is called.'}</p></div><div class="button-row">${button('Grant sample permission','grant','primary',`data-key="${key}"`)}${button('Simulate permission denial','deny','outline',`data-key="${key}"`)}${button('Disconnect','disconnect','quiet',`data-key="${key}"`)}</div>`);}
function buildStart(){if(p().builtRevision){go('build');return;}dispatch('BUILD_START');buildStep=0;go('build');const id=p().id;clearInterval(timer);timer=setInterval(()=>{buildStep++;if(buildStep>=4){clearInterval(timer);dispatchFor(id,'BUILD_DONE');notify('Preview ready. Add or open a record to explore your workflow.');}else render();},700);}
function deployStart(fail=false){dispatch('DEPLOY_START');const id=p().id;setTimeout(()=>{try{dispatchFor(id,fail?'DEPLOY_FAIL':'DEPLOY_DONE');}catch(err){notify(err.message,true);}},1200);}
function exportProject(){const x=p();const payload={format:'architect2-project-export',schema:1,project:x,files:fileMap(x),notice:'Local prototype export. No credentials or runnable framework adapters included.'};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='architect-project.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Project and derived configuration exported.');}
document.addEventListener('click',event=>{if(event.target.closest('.skip-link')){event.preventDefault();document.querySelector('#main')?.focus();return;}const el=event.target.closest('[data-action]');if(!el)return;const {action,value,id,key}=el.dataset;try{switch(action){
  case 'demo':state.session={name:'Reviewer',role:'Build a business workflow'};closeModal();if(!state.projects.length)startProject(createProject());else{save();go('home');}break;
  case 'auth':if(state.session){state.session=null;save();render();notify('Signed out of the local demo. Projects remain on this device.');}else auth();break;
  case 'mode':state.mode=value;save();render();break;
  case 'close':closeModal();break;
  case 'import':importDialog();break;
  case 'load-sample':document.querySelector('#import-json').value=JSON.stringify(sampleImport,null,2);break;
  case 'open-project':previewSearch='';state.active=id;save();go(p().builtRevision?'build':'plan');break;
  case 'template':{const b=blueprints[value]||blueprints.custom;showModal(e(b.name),`<p>${e(b.outcome)}</p><div class="callout"><strong>What you start with</strong><p>${b.agents.length} agent roles · ${e(b.layout)} layout · ${e(b.plural)} data · project-specific knowledge</p></div><ul>${b.agents.map(a=>'<li>'+e(a.name)+' — '+e(a.role)+'</li>').join('')}</ul>${button('Use this template','create-template','primary',`data-value="${b.id}"`)}`);break;}
  case 'create-template':startProject(createProject(undefined,false,value));break;
  case 'add-agent':agentDialog();break;
  case 'edit-agent':agentDialog(id);break;
  case 'remove-agent':dispatch('AGENT_REMOVE',{id});break;
  case 'add-record':recordDialog();break;
  case 'discover':showModal('Find a useful starting point',`<form id="discovery-form"><label for="discovery-role">Your role</label><input name="role" id="discovery-role" required placeholder="Product manager, support lead, founder…"><label for="bottleneck">What slows the team down?</label><textarea id="bottleneck" name="bottleneck" required placeholder="Researching accounts, answering tickets, organizing requests…"></textarea><label for="stack">Tools you already use</label><input name="stack" id="stack" placeholder="CRM, knowledge base, Slack or Teams"><button class="btn primary" type="submit">Find a starting point</button></form>`);break;
  case 'filter':filter=value;render();break;
  case 'build-start':buildStart();break;
  case 'cancel-build':clearInterval(timer);dispatch('BUILD_CANCEL');break;
  case 'work-tab':tab=value;render();break;
  case 'file':selectedFile=value;render();break;
  case 'suggest':document.querySelector('#change-request').value=value;document.querySelector('#change-request').focus();break;
  case 'apply':dispatch('APPLY');notify('Change applied across the workspace. Run the current revision’s tests before release.');break;
  case 'discard':dispatch('DISCARD');break;
  case 'undo':dispatch('UNDO');notify('Previous configuration restored.');break;
  case 'agents':case 'data':case 'test':go(action);break;
  case 'release':go('deploy');break;
  case 'connect':connectDialog(key);break;
  case 'grant':case 'deny':case 'disconnect':dispatch('CONNECTION',{key,status:action==='grant'?'connected':action==='deny'?'denied':'missing'});closeModal();notify(action==='grant'?'Sample connection ready.':'Connection state updated.');break;
  case 'add-source':showModal('Add knowledge source',`<p>Record a source’s name and purpose locally. Document ingestion is deferred.</p><form id="source-form"><label for="source-name">Source name</label><input id="source-name" name="name" required placeholder="Product documentation, playbook, research library…"><div class="form-error" role="alert"></div><button class="btn primary" type="submit">Add source metadata</button></form>`);break;
  case 'studio':showModal('Reuse a Studio agent',`<div class="row"><span class="agent-icon">↗</span>${badge('Sample library')}</div><h3>Review coordinator</h3><p>Reference: <code>studio:sample-review-coordinator:v1</code></p><p>Converts a structured result into a review assignment. It can be reused across support, research, operations and custom applications.</p><details><summary>Inspect contract</summary><pre>input: finding, citations, reviewOwner
output: draftAction, requiresHuman: true
tool: review.create</pre></details>${p()?button(p().studio?'Reference already attached':'Attach sample reference','attach-studio','primary',p().studio?'disabled':''):'<p>Open a project to attach this agent.</p>'}`);break;
  case 'attach-studio':dispatch('STUDIO');closeModal();break;
  case 'retry-test':dispatch('TEST',{kind:'normal'});break;
  case 'github-connect':showModal('Authorize sample GitHub',`<p>Requested permissions: read repository metadata and write reviewed project changes to a selected branch.</p><p>This is a local authorization simulation. No GitHub account is accessed.</p>${button('Authorize sample account','authorize-github','primary')}`);break;
  case 'authorize-github':dispatch('GITHUB_CONNECT');closeModal();break;
  case 'sync':dispatch('GITHUB_SYNC');notify('Sample destination now matches the current revision.');break;
  case 'conflict':dispatch('GITHUB_CONFLICT');break;
  case 'resolve-local':case 'resolve-remote':dispatch('GITHUB_RESOLVE',{choice:action.endsWith('remote')?'remote':'local'});break;
  case 'retry-deploy':deployStart();break;
  case 'rollback':showModal('Restore this release?',`<p>This restores the app and agent configuration from the selected version. Current connection permissions remain unchanged. New tests are required for another release.</p>${button('Restore version','confirm-rollback','primary',`data-id="${id}"`)}`);break;
  case 'confirm-rollback':dispatch('ROLLBACK',{id});closeModal();notify('Release configuration restored.');break;
  case 'released-preview':{const r=p().releases.find(r=>r.id===p().activeRelease);showModal('Released sample preview',preview({...p(),...r.snapshot}));break;}
  case 'exception':{const r=p().records.find(r=>r.id===id);showModal(e(r.id)+' · '+e(p().entity),`<h3>${e(r.title)}</h3><p>${e(r.description)}</p><div class="callout"><strong>${r.confidence*100<p().threshold?'Human review required':'Draft ready for review'}</strong><p>Confidence: ${Math.round(r.confidence*100)}%. Reference: ${e(projectBlueprint(p()).citation)}. Owner: ${e(p().owner)}.</p></div>${p().fields.map(f=>'<p><strong>'+e(f)+':</strong> '+e(r.values?.[f]||'Not supplied')+'</p>').join('')}<form id="record-stage-form"><input type="hidden" name="id" value="${e(r.id)}"><label for="record-stage">Workflow stage</label><select id="record-stage" name="stage">${p().stages.map(stage=>`<option ${stage===r.stage?'selected':''}>${e(stage)}</option>`).join('')}</select><button class="btn outline" type="submit">Move to stage</button></form>${button('Assign human review','assign-review','primary',`data-id="${id}"`)}`);break;}
  case 'assign-review':dispatch('REVIEW',{id});closeModal();notify('Review assigned locally. No notification was sent.');break;
  case 'share':showModal('Share the prototype',`<p>This link opens the hosted prototype. Project edits remain on each person’s device; this is not cloud collaboration.</p><label for="share-url">Prototype link</label><input id="share-url" readonly value="${e(location.href.split('#')[0])}"><div class="button-row">${button('Copy link','copy-link','primary')}${p()?button('Export current project','export','outline'):''}</div><p class="subtle">The exported JSON contains your local project and sample history. Do not add confidential data.</p>`);break;
  case 'copy-link':navigator.clipboard?.writeText(location.href.split('#')[0]).then(()=>notify('Prototype link copied.')).catch(()=>notify('Select the link above and copy it manually.',true));break;
  case 'export':exportProject();break;
  case 'reset':showModal('Reset this demo?',`<p>This clears the prototype’s projects and local demo identity on this device. Export any project you want to keep first.</p>${button('Clear local demo data','confirm-reset','danger-button')}`);break;
  case 'confirm-reset':clearInterval(timer);drafts.clear();state=initialState();save();closeModal();go('home');notify('Demo reset.');break;
  case 'about':showModal('A prototype with clear boundaries',`<h3>Working on this device</h3><p>Project state, editable plans, configuration, change-impact review, undo, configurable inbox, board, and brief previews, validation, release gates, history, exports, and browser persistence.</p><h3>Deterministic simulations</h3><p>Sign-in, AI generation, Studio reuse, agent runs, external connections, GitHub synchronization, invitations, and sample-app deployment.</p><h3>Not implemented</h3><p>Real model inference, server authentication, cloud database, arbitrary repository cloning, runtime framework adapters, and simultaneous collaboration.</p><p>The Architect prototype itself can be hosted as a real website. Its internal sample release flow remains simulated.</p>`);break;
}}catch(err){notify(err.message,true);}});
document.addEventListener('submit',event=>{const f=event.target,formId=f.getAttribute('id');if(!formId)return;event.preventDefault();const d=Object.fromEntries(new FormData(f));try{switch(formId){
  case 'new-project':startProject(createFromPrompt(d.outcome,d.blueprint));break;
  case 'auth-form':state.session={name:d.name,role:d.role};state.mode=d.role.includes('codebase')?'technical':'guided';save();closeModal();render();if(state.mode==='technical')importDialog();break;
  case 'import-form':{const m=inspectImport(d.manifest);const x=createProject(m.name,true,m.blueprintId);x.messages=[{role:'assistant',text:'Imported '+m.files.length+' file entries with '+m.framework+' configuration. Review missing environment names: '+(m.requiredEnv.join(', ')||'None')+'. Source execution is simulated.'}];x.importInfo=m;x.framework=m.framework;state.mode='technical';startProject(x);notify(`Imported manifest: ${m.files.length} files; ${m.requiredEnv.length} configuration requirements. Source is simulated.`);break;}
  case 'plan-form':dispatch('PLAN',d);go('agents');break;
  case 'agent-form':dispatch('AGENT',d);notify('Agent configuration saved.');break;
  case 'chat-form':dispatch('PROPOSE',d);break;
  case 'config-form':{let config;try{config=JSON.parse(d.config);}catch{throw new Error('Invalid JSON. Your edit is preserved.');}const x=p(),allowed=['name','outcome','owner','reviewBelow','responseHours','notifications','layout'];if(Object.keys(config).some(k=>!allowed.includes(k)))throw new Error('Unknown configuration key. Use only the displayed fields.');if(typeof config.name!=='string'||!config.name.trim()||config.name.length>80||typeof config.outcome!=='string'||!config.outcome.trim()||typeof config.owner!=='string'||!config.owner.trim()||!Number.isFinite(config.reviewBelow)||config.reviewBelow<50||config.reviewBelow>99||!Number.isFinite(config.responseHours)||config.responseHours<1||config.responseHours>168||typeof config.notifications!=='boolean'||!layouts.includes(config.layout))throw new Error('Check field types, review threshold (50–99), and response window (1–168).');x.pending={title:'Update app configuration',text:'Edited configuration',baseRevision:x.revision,patch:{name:config.name,outcome:config.outcome,owner:config.owner,threshold:config.reviewBelow,sla:config.responseHours,notifications:config.notifications,layout:config.layout},impact:[{layer:'Interface',detail:'Update the app title, inbox indicators, and response window.'},{layer:'Agents',detail:'Update review routing and the named owner.'},{layer:'Connections',detail:config.notifications?'Teams permission is required.':'No notification connection required.'}]};save();render();notify('Review the proposed configuration in Change impact.');break;}
  case 'source-form':dispatch('KNOWLEDGE',d);closeModal();break;
  case 'test-form':dispatch('TEST',d);break;
  case 'github-form':dispatch('GITHUB_CONFIG',{...d,automatic:new FormData(f).has('automatic')});notify('Destination saved. Review and sync the current revision.');break;
  case 'deploy-form':deployStart(d.scenario==='fail');break;
  case 'member-form':dispatch('MEMBER',d);notify('Added to the local access list. No invitation sent.');break;
  case 'settings-form':dispatch('SETTINGS',d);notify('Project settings saved.');break;
  case 'discovery-form':{const kind=inferBlueprint(d.role+' '+d.bottleneck),b=blueprints[kind];showModal('A starting point to explore',`<p>Based on the terms you supplied, this demo suggests <strong>${e(b.name)}</strong>. You can change the starting point.</p><p>${e(b.outcome)}</p><p>Existing tools: ${e(d.stack||'Not specified')}.</p><p class="subtle">Rule-based suggestion, not customer research or an AI assessment.</p>${button('Review suggested template','template','primary',`data-value="${kind}"`)}`);break;}
  case 'structure-form':dispatch('STRUCTURE',{...d,fields:d.fields.split(',').map(v=>v.trim()).filter(Boolean),stages:d.stages.split(',').map(v=>v.trim()).filter(Boolean)});notify('Application structure updated. Open Preview to inspect it.');break;
  case 'agent-detail-form':dispatch(d.id?'AGENT_EDIT':'AGENT_ADD',{...d,tools:new FormData(f).getAll('tools')});closeModal();break;
  case 'record-form':dispatch('RECORD_ADD',{...d,values:Object.fromEntries(p().fields.map((field,i)=>[field,d['field'+i]||'']))});closeModal();break;
  case 'record-stage-form':dispatch('RECORD_STAGE',d);closeModal();break;
}for(const input of f.querySelectorAll('[id]'))drafts.delete((state.active||'home')+':'+input.id);render();}catch(err){const error=f.querySelector('.form-error');if(error){error.textContent=err.message;error.tabIndex=-1;error.focus();}else notify(err.message,true);}});
document.addEventListener('input',event=>{if(event.target.id&&event.target.matches('input,textarea,select'))drafts.set((state.active||'home')+':'+event.target.id,event.target.type==='checkbox'?event.target.checked:event.target.value);if(event.target.id==='preview-search'){previewSearch=event.target.value;const position=event.target.selectionStart;render();const input=document.querySelector('#preview-search');input.focus();input.setSelectionRange(position,position);}if(event.target.id==='project-search'){search=event.target.value;const position=event.target.selectionStart;render();const input=document.querySelector('#project-search');input.focus();input.setSelectionRange(position,position);}});
render();
